DELIMITER $$
CREATE PROCEDURE stu_proc1(IN p_dept VARCHAR(20), IN p_name VARCHAR(20))
BEGIN
SELECT s.Sno,s.Sname,TIMESTAMPDIFF(YEAR,s.Birth,CURDATE()),c.Cname,x.Grade FROM student s JOIN sc x USING(Sno) JOIN course c USING(Cno) WHERE s.Sdept LIKE COALESCE(p_dept,'%') AND s.Sname LIKE COALESCE(p_name,'林%');
END$$
DELIMITER ;

DELIMITER $$
CREATE PROCEDURE student_sc(IN p_start CHAR(8), IN p_end CHAR(8))
BEGIN
SELECT s.Sno,s.Sname,SUM(x.Grade) FROM student s LEFT JOIN sc x USING(Sno) WHERE s.Sno BETWEEN p_start AND p_end GROUP BY s.Sno,s.Sname;
END$$
DELIMITER ;

DELIMITER $$
CREATE PROCEDURE update_sc(IN p_sno CHAR(8), IN p_cno CHAR(3), IN p_grade TINYINT)
BEGIN
UPDATE sc SET Grade=p_grade WHERE Sno=p_sno AND Cno=p_cno;
END$$
DELIMITER ;

DELIMITER $$
CREATE PROCEDURE course_average(IN p_cno CHAR(3), OUT p_avg DECIMAL(6,2))
BEGIN
SELECT AVG(Grade) INTO p_avg FROM sc WHERE Cno=p_cno;
END$$
DELIMITER ;

DELIMITER $$
CREATE PROCEDURE course_average_report(IN p_cno CHAR(3))
BEGIN
  CALL course_average(p_cno,@average);
  SELECT CONCAT(Cname,'课程的平均成绩为：',COALESCE(@average,'无成绩'),
                IF(@average<60,'，其平均分未达60分','')) AS message
  FROM course WHERE Cno=p_cno;
END$$
DELIMITER ;

