DELIMITER $$
CREATE PROCEDURE practice_absences(IN p_cno CHAR(3))
BEGIN
SELECT s.Sno,s.Sname FROM student s JOIN sc x USING(Sno) WHERE x.Cno=p_cno AND x.Grade IS NULL;
END$$
DELIMITER ;

DELIMITER $$
CREATE PROCEDURE practice_exam_counts(IN p_cno CHAR(3), OUT p_selected INT, OUT p_graded INT)
BEGIN
SELECT COUNT(*),COUNT(Grade) INTO p_selected,p_graded FROM sc WHERE Cno=p_cno;
END$$
DELIMITER ;

DELIMITER $$
CREATE PROCEDURE practice_add_credit(IN p_cno CHAR(3), INOUT p_total INT)
BEGIN
SET p_total=p_total+COALESCE((SELECT Credit FROM course WHERE Cno=p_cno),0);
END$$
DELIMITER ;

DELIMITER $$
CREATE PROCEDURE practice_grade_status(IN p_grade INT)
BEGIN
SELECT CASE WHEN p_grade IS NULL THEN '缺考' WHEN p_grade<0 OR p_grade>100 THEN '无效' WHEN p_grade<60 THEN '不及格' ELSE '及格' END;
END$$
DELIMITER ;

DELIMITER $$
CREATE PROCEDURE practice_grade_band(IN p_cno CHAR(3), IN p_min INT, IN p_max INT)
BEGIN
IF p_min>p_max THEN SELECT NULL; ELSE SELECT COUNT(*) FROM sc WHERE Cno=p_cno AND Grade BETWEEN p_min AND p_max; END IF;
END$$
DELIMITER ;
